use std::sync::Mutex;
use std::time::{Duration, Instant};

pub type Item = Vec<(String, Vec<u8>)>;

pub const SENSITIVE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

pub trait Pasteboard {
    type Snapshot;

    fn change_count(&self) -> i64;
    fn snapshot(&mut self) -> Option<Self::Snapshot>;
    fn write_text(&mut self, text: &str) -> Result<(), String>;
    fn restore(&mut self, snapshot: Self::Snapshot) -> Result<(), String>;
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Limits {
    pub max_types: usize,
    pub max_bytes: usize,
    pub budget: Duration,
}

impl Default for Limits {
    fn default() -> Self {
        Self {
            max_types: 64,
            max_bytes: 20 * 1024 * 1024,
            budget: Duration::from_millis(300),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Gathered {
    Items(Vec<Item>),
    Sensitive,
    OverBudget,
}

pub fn gather(
    types: &[Vec<String>],
    limits: &Limits,
    mut read: impl FnMut(usize, &str) -> Option<Vec<u8>>,
) -> Gathered {
    let count: usize = types.iter().map(Vec::len).sum();
    if types
        .iter()
        .flatten()
        .any(|kind| SENSITIVE_TYPES.contains(&kind.as_str()))
    {
        return Gathered::Sensitive;
    }
    if count > limits.max_types {
        return Gathered::OverBudget;
    }
    let started = Instant::now();
    let mut bytes = 0usize;
    let mut items = Vec::with_capacity(types.len());
    for (index, kinds) in types.iter().enumerate() {
        let mut item = Item::new();
        for kind in kinds {
            if started.elapsed() > limits.budget {
                return Gathered::OverBudget;
            }
            if let Some(data) = read(index, kind) {
                bytes = bytes.saturating_add(data.len());
                if bytes > limits.max_bytes {
                    return Gathered::OverBudget;
                }
                item.push((kind.clone(), data));
            }
        }
        items.push(item);
    }
    Gathered::Items(items)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Ticket(u64);

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Restore {
    Restored,
    ClipboardChanged,
    Superseded,
    Failed(String),
}

struct Slot<S> {
    snapshot: Option<S>,
    written: i64,
    ticket: u64,
}

pub struct Clipboard<S> {
    slot: Mutex<Slot<S>>,
}

impl<S> Default for Clipboard<S> {
    fn default() -> Self {
        Self::new()
    }
}

impl<S> Clipboard<S> {
    pub const fn new() -> Self {
        Self {
            slot: Mutex::new(Slot {
                snapshot: None,
                written: 0,
                ticket: 0,
            }),
        }
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Slot<S>> {
        self.slot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    pub fn put_text<P: Pasteboard<Snapshot = S>>(
        &self,
        pasteboard: &mut P,
        text: &str,
        restore: bool,
    ) -> Result<Option<Ticket>, String> {
        let mut slot = self.lock();
        slot.ticket += 1;
        let ours = slot.snapshot.is_some() && pasteboard.change_count() == slot.written;
        if !restore {
            slot.snapshot = None;
        } else if !ours {
            slot.snapshot = pasteboard.snapshot();
        }
        if let Err(error) = pasteboard.write_text(text) {
            slot.snapshot = None;
            return Err(error);
        }
        slot.written = pasteboard.change_count();
        Ok(slot.snapshot.is_some().then_some(Ticket(slot.ticket)))
    }

    pub fn restore<P: Pasteboard<Snapshot = S>>(
        &self,
        pasteboard: &mut P,
        ticket: Ticket,
    ) -> Restore {
        let mut slot = self.lock();
        if slot.ticket != ticket.0 {
            return Restore::Superseded;
        }
        let Some(snapshot) = slot.snapshot.take() else {
            return Restore::Superseded;
        };
        if pasteboard.change_count() != slot.written {
            return Restore::ClipboardChanged;
        }
        match pasteboard.restore(snapshot) {
            Ok(()) => Restore::Restored,
            Err(error) => Restore::Failed(error),
        }
    }

    pub fn restore_pending<P: Pasteboard<Snapshot = S>>(&self, pasteboard: &mut P) -> Restore {
        let mut slot = self.lock();
        slot.ticket += 1;
        let Some(snapshot) = slot.snapshot.take() else {
            return Restore::Superseded;
        };
        if pasteboard.change_count() != slot.written {
            return Restore::ClipboardChanged;
        }
        match pasteboard.restore(snapshot) {
            Ok(()) => Restore::Restored,
            Err(error) => Restore::Failed(error),
        }
    }
}
